{
  "sql": "SELECT COUNT(DISTINCT seller_id) AS num_vendedores, SUM(ingresos) AS ingresos_totales FROM ( SELECT seller_id, SUM(price) AS ingresos, AVG(review_score) AS calificacion, SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS pct_retrasos FROM vw_ingresos_por_vendedor INNER JOIN vw_entregas_retrasos ON vw_ingresos_por_vendedor.seller_id = vw_entregas_retrasos.seller_id WHERE pedidos >= 30 GROUP BY seller_id ) WHERE (calificacion < 3.5 OR pct_retrasos > 15) AND ingresos >= ( SELECT ingresos FROM ( SELECT seller_id, SUM(price) AS ingresos FROM vw_ingresos_por_vendedor WHERE pedidos >= 30 GROUP BY seller_id ) ORDER BY ingresos DESC LIMIT 1 OFFSET 24 )"
}

